                    "sql": "create or replace table RPSG_DB.maplemonk.sales_consolidated_intermediate_ecom as select final_marketplace as SHOP_NAME ,awb ,CARRIER_ID ,COURIER ,CUSTOMER_NAME ,EMAIL ,contact_num as phone ,final_marketplace as marketplace ,MARKETPLACE_ID ,ORDER_ID ,SUBORDER_Id ::varchar as SUBORDER_Id ,INVOICE_ID :: varchar as INVOICE_ID ,REFERENCE_CODE ,MANIFEST_DATE ::timestamp as MANIFEST_DATE ,SHIPPING_LAST_UPDATE_DATE ::timestamp as SHIPPING_LAST_UPDATE_DATE ,upper(SHIPPING_STATUS::varchar) SHIPPING_STATUS ,b.SKU ::varchar as SKU ,b.SKU_TYPE :: varchar as SKU_TYPE ,b.PRODUCT_ID ::varchar as PRODUCT_ID ,b.PRODUCTNAME ::varchar as PRODUCTNAME ,CURRENCY ::varchar as CURRENCY ,IS_REFUND :: int as IS_REFUND ,CITY ,STATe ,ORDER_STATUS ,ORDER_DATE ::Date as order_date ,ORDER_DATE as order_timestamp ,SHIPPING_PRICE ,NUMBER_OF_PRODUCTS_IN_COMBO ,null SUBORDER_QUANTITY ,SHIPPED_QUANTITY ,RETURNED_QUANTITY ,CANCELLED_QUANTITY ,RETURN_SALES ,CANCEL_SALES ,TAX ,SUBORDER_MRP ,upper(coalesce(s.CATEGORY,b.category)) category ,upper(coalesce(s.PRODUCT_NAME,b.PRODUCTNAME)) Product_Name_Mapped ,S.Report_Category ,null Product_Pack ,null Product_quantity ,DISCOUNT ,SELLING_PRICE ,MRP_SALES ,DISCOUNT_MRP ,NEW_CUSTOMER_FLAG ,NEW_CUSTOMER_FLAG_MONTH ,WAREHOUSE_NAME ,case when upper(shipping_STATUS) in (\'RETURNED\', \'RTO\') and order_date::date >= \'2024-05-01\' then 1 else 0 end as return_flag ,case when upper(shipping_STATUS) in (\'DELIVERED\',\'DELIVERED TO ORIGIN\', \'RETURNED\', \'RTO\') then datediff(day,date(b.ORDER_DATE),date(shipping_Last_update_date)) else datediff(day,date(b.ORDER_DATE), getdate()) end::int AS DAYS_IN_SHIPMENT ,CHANNEL ::varchar as CHANNEL ,NULL as Shopify_UTM_source ,NULL as Shopify_UTM_Medium ,NULL AS UTM_CAMPAIGN ,PAYMENT_MODE ,IMPORT_DATE ,LAST_UPDATE_DATE ,invoice_date ,company_name ,b.pin_code ,NULL as FINAL_UTM_CAMPAIGN ,\'Synced\' as EasyEcom_Sync_Flag, case when cancel_sales is not null then LAST_UPDATE_DATE end as cancelled_at ,\'DRV\' as Data_Source ,s.MARKETPLACE_SKU as exception_sku from (SELECT *,case when upper(CUSTOMER_NAME) like \'%NATURE-FIT HEALTHTECH PRIVATE LIMITED%\' then \'NATUREFIT\' when upper(CUSTOMER_NAME) like \'%CLOUDSTORE RETAIL PRIVATE LIMITED%\' then \'SWIGGY\' when upper(CUSTOMER_NAME) like \'%SCOOTSY LOGISTICS PRIVATE LIMITED%\' then \'SWIGGY\' when upper(CUSTOMER_NAME) like \'%GROWFITTER PRIVATE LIMITED%\' then \'GROWFITTER\' when upper(marketplace) like \'%AMAZON%\' then \'AMAZON\' when upper(marketplace) like \'%FLIPKART%\' then \'FLIPKART\' when upper(marketplace) like \'%MEESHO%\' then \'MEESHO\' when upper(marketplace) like \'%JIO MART%\' then \'JIOMART\' when upper(marketplace) like \'%CRED-API%\' then \'CRED\' when upper(marketplace) like \'%CRED-API2%\' then \'CRED\' when upper(marketplace) like \'%GOQII%\' then \'GOQII\' when upper(marketplace) like \'%HEALTH MUG%\' then \'HEALTH MUG\' when upper(marketplace) like \'%HEALTHXP%\' then \'HEALTHXP\' when upper(marketplace) like \'%HEALTH KART%\' then \'HEALTH KART\' when upper(marketplace) like \'%MYNTRA%\' then \'MYNTRA\' when upper(marketplace) like \'%NATUREFIT%\' then \'NATUREFIT\' when upper(marketplace) like \'%PHARMEASY%\' then \'PHARMEASY\' when upper(marketplace) like \'%SMYTTEN%\' then \'SMYTTEN\' when upper(marketplace) like \'%SNAPDEAL%\' then \'SNAPDEAL\' when upper(marketplace) like \'%TELEONE%\' then \'TELEONE\' when upper(marketplace) like \'%NATUREFIT%\' then \'NATUREFIT\' when upper(marketplace) like \'%TRELL%\' then \'TRELL\' when upper(marketplace) like \'%WMALL%\' then \'WMALL\' when upper(marketplace) like \'%1MG%\' then \'1MG\' else upper(marketplace) end as final_marketplace , row_number() over(partition by lower(ifnull(reference_code,\'\')),lower(ifnull(sku,\'\')),lower(ifnull(SUBORDER_ID,\'\')) order by order_date desc)rw FROM rpsg_DB.maplemonk.fact_items_easyecom_drv WHERE upper(final_marketplace) LIKE ANY (\'%AMAZON%\', \'%FLIPKART%\', \'%MEESHO%\', \'%JIO MART%\', \'%PHARMEASY%\',\'%CRED%\', \'%SNAPDEAL%\', \'%HEALTH MUG%\', \'%SMYTTEN%\', \'%GOQII%\', \'%FIRSTCRY%\', \'%TELEONE%\', \'%TRELL%\', \'%WMALL%\' , \'%1MG%\' , \'%NATUREFIT%\',\'%MYNTRA%\' ,\'%HEALTHXP%\' ,\'%HEALTH KART%\', \'%SWIGGY%\', \'%GROWFITTER%\') and lower(SKU) NOT IN (SELECT DISTINCT (SKU) FROM rpsg_DB.maplemonk.three60_sku_master) ) b left join ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE as maketplace_map, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, \"Report Category\" AS REPORT_CATEGORY, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null) where rw=1 ) S on lower(SPLIT_PART(b.sku, \'-\', 1))=lower(s.sku) where b.rw=1 and s.sku is not null; create or replace table rpsg_db.maplemonk.sales_consolidated_amazon_ecom_orders as select case when upper(EEF.SHOP_NAME) like \'%AMAZON%\' then \'AMAZON\' else upper(EEF.SHOP_NAME) end as SHOP_NAME ,EEF.awb ,EEF.CARRIER_ID ,EEF.COURIER ,EEF.CUSTOMER_NAME ,EEF.EMAIL ,EEF.contact_num as phone ,\'AMAZON\' as marketplace, null as MARKETPLACE_ID, AM.ORDER_ID, LINE_ITEM_ID::varchar as suborder_id, EEF.INVOICE_ID, AM.ORDER_ID as reference_code, eef.manifest_date, null as SHIPPING_LAST_UPDATE_DATE, upper(EEF.SHIPPING_STATUS) SHIPPING_STATUS, AM.sku, null as sku_type, AM.product_id, product_name_final as product_name, null as currency, AM.is_refund, AM.city, AM.state, case when lower(am.order_status) like \'%cancel%\' then \'cancelled\' when lower(am.order_status) like \'%return%\' then \'returned\' else am.order_status end order_status, order_timestamp :: date as order_date, order_timestamp, AM.shipping_price, null as NUMBER_OF_PRODUCTS_IN_COMBO, quantity as suborder_quantity, null as SHIPPED_QUANTITY, null as RETURNED_QUANTITY, null as CANCELLED_QUANTITY, null as RETURN_SALES, null as CANCEL_SALES, coalesce(eef.SELLING_PRICE,total_sales)* 0.13 as tax, null as SUBORDER_MRP, UPPER(coalesce(s.Category,AM.category)) as category, UPPER(product_name_final) as Product_Name_Mapped, null as Report_Category, null as Product_Pack, null as Product_quantity, null as DISCOUNT, coalesce(eef.SELLING_PRICE,total_sales) as selling_price, null as MRP_SALES, null as DISCOUNT_MRP, null as NEW_CUSTOMER_FLAG, null as NEW_CUSTOMER_FLAG_MONTH, WAREHOUSE_NAME, AM.is_refund as return_flag, null as DAYS_IN_SHIPMENT, \'AMAZON\' as CHANNEL, NULL as Shopify_UTM_source, NULL as Shopify_UTM_Medium, NULL AS UTM_CAMPAIGN, eef.payment_mode, null as IMPORT_DATE, null as LAST_UPDATE_DATE, null as INVOICE_DATE, null as company_name, null as pin_code, NULL as FINAL_UTM_CAMPAIGN, \'Synced\' as EasyEcom_Sync_Flag, null as cancelled_at, \'AMAZON\' as Data_Source ,s.MARKETPLACE_SKU as exception_sku from (SELECT * FROM RPSG_DB.MAPLEMONK.RPSG_DB_amazon_fact_items WHERE lower(product_name) NOT LIKE \'%three60%\') AM LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )EEF ON AM.ORDER_ID = EEF.reference_code AND LOWER(AM.SKU) = LOWER(EEF.SKU) left join (select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null ) where rw=1 ) AS S ON lower(AM.sku) = lower(S.sku) UNION ALL select \'MEESHO\' as SHOP_NAME ,EEF.awb ,EEF.CARRIER_ID ,EEF.COURIER ,EEF.CUSTOMER_NAME ,EEF.EMAIL ,EEF.contact_num as phone ,\'MEESHO\' as marketplace, null as MARKETPLACE_ID, split(AM.\"Sub Order No\",\'_\')[0]::string ORDER_ID, \"Sub Order No\"::varchar as suborder_id, EEF.INVOICE_ID, split(AM.\"Sub Order No\",\'_\')[0]::string as reference_code, eef.manifest_date, null as SHIPPING_LAST_UPDATE_DATE, upper(EEF.SHIPPING_STATUS) SHIPPING_STATUS, AM.sku, null as sku_type, null as product_id, UPPER(coalesce(product_name,\"Product Name\")) as product_name, null as currency, null is_refund, null as city, \"Customer State\" as state, case when lower(am.\"Reason for Credit Entry\") like \'%cancel%\' then \'cancelled\' when lower(am.\"Reason for Credit Entry\") like \'%return%\' then \'returned\' else lower(am.\"Reason for Credit Entry\") end order_status, COALESCE( TRY_TO_DATE(\"Order Date\", \'MM/DD/YYYY\'), TRY_TO_DATE(\"Order Date\", \'DD-MM-YY\') ) AS order_date, order_date as order_timestamp, null as shipping_price, null as NUMBER_OF_PRODUCTS_IN_COMBO, QUANTITY::int as suborder_quantity, null as SHIPPED_QUANTITY, null as RETURNED_QUANTITY, null as CANCELLED_QUANTITY, null as RETURN_SALES, null as CANCEL_SALES, (\"Supplier Listed Price (Incl. GST + Commission)\"::int * 0.13 ) as tax, null as SUBORDER_MRP, s.CATEGORY as category, UPPER(coalesce(product_name,\"Product Name\")) as Product_Name_Mapped, null as Report_Category, null as Product_Pack, null as Product_quantity, null as DISCOUNT, \"Supplier Listed Price (Incl. GST + Commission)\"::int as selling_price, null as MRP_SALES, null as DISCOUNT_MRP, null as NEW_CUSTOMER_FLAG, null as NEW_CUSTOMER_FLAG_MONTH, null WAREHOUSE_NAME, null as return_flag, null as DAYS_IN_SHIPMENT, \'MEESHO\' as CHANNEL, NULL as Shopify_UTM_source, NULL as Shopify_UTM_Medium, NULL AS UTM_CAMPAIGN, eef.payment_mode, null as IMPORT_DATE, null as LAST_UPDATE_DATE, null as INVOICE_DATE, null as company_name, null as pin_code, NULL as FINAL_UTM_CAMPAIGN, \'Synced\' as EasyEcom_Sync_Flag, null as cancelled_at, \'MEESHO\' as Data_Source ,s.MARKETPLACE_SKU as exception_sku FROM RPSG_DB.MAPLEMONK.sales_report_meesho_order_report AM LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )EEF ON lower(split(AM.\"Sub Order No\",\'_\')[0]::string ) = lower(EEF.reference_code) AND LOWER(AM.SKU) = LOWER(EEF.SKU) left join (select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null ) where rw=1 ) AS S ON lower(AM.sku) = lower(S.sku) UNION ALL SELECT \'FLIPKART\' temp_SHOP_NAME, NULL AS awb, NULL AS CARRIER_ID, NULL AS COURIER, NULL AS CUSTOMER_NAME, NULL AS EMAIL, NULL AS phone, \'Flipkart\' AS MARKETPLACE, NULL AS MARKETPLACE_ID, \"Order ID\" as order_id, \"Order Item ID\"::VARCHAR AS SUBORDER_Id, \"Buyer Invoice ID\"::VARCHAR AS INVOICE_ID, \"Order ID\" AS REFERENCE_CODE, NULL AS MANIFEST_DATE, NULL AS SHIPPING_LAST_UPDATE_DATE, NULL AS SHIPPING_STATUS, (REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))::VARCHAR SKU, NULL AS SKU_TYPE, marketplace_sku AS PRODUCT_ID, S.PRODUCT_NAME::VARCHAR AS PRODUCTNAME, NULL AS CURRENCY, NULL AS IS_REFUND, NULL AS CITY, \"Customer\'s Delivery State\" AS STATE, case when lower(\"Event Type\") like \'%cancel%\' then \'cancelled\' when lower(\"Event Type\") like \'%sale%\' then \'delivered\' when lower(\"Event Type\") like \'%return%\' then \'RTO\' else \"Event Type\" end AS ORDER_STATUS, try_TO_TIMESTAMP(replace(b.\"Order Date\",\'/\',\'-\'), \'YYYY-MM-DD HH24:MI:SS.FF\')::date AS order_date, try_TO_TIMESTAMP(replace(b.\"Order Date\",\'/\',\'-\'), \'YYYY-MM-DD HH24:MI:SS.FF\')::date AS order_timestamp, try_cast(\"Shipping Charges\" as int ) shipping_charges, NULL AS NUMBER_OF_PRODUCTS_IN_COMBO, try_cast(\"Item Quantity\" as int) AS suborder_quantity, null as SHIPPED_QUANTITY, NULL AS RETURNED_QUANTITY, NULL AS CANCELLED_QUANTITY, NULL AS RETURN_SALES, NULL AS CANCEL_SALES, (coalesce(eef.SELLING_PRICE,try_cast(\"Price before discount\" as float))*0.13 ) as tax , null AS SUBORDER_MRP, UPPER(S.Category) AS category, UPPER(S.PRODUCT_NAME) AS Product_Name_Mapped, null AS Report_Category, null AS Product_Pack, try_cast(\"Item Quantity\" as int) AS Product_quantity, try_Cast(\"Total Discount\" as float) AS DISCOUNT, coalesce(eef.SELLING_PRICE,try_cast(\"Price before discount\" as float)) as selling_price, null AS MRP_SALES, try_cast(\"Total Discount\" as int) AS DISCOUNT_MRP, NULL AS NEW_CUSTOMER_FLAG, NULL AS NEW_CUSTOMER_FLAG_MONTH, null AS WAREHOUSE_NAME, NULL AS RETURN_FLAG, NULL AS DAYS_IN_SHIPMENT, NULL AS CHANNEL, NULL AS Shopify_UTM_source, NULL AS Shopify_UTM_Medium, NULL AS UTM_CAMPAIGN, coalesce(\"Order Type\",EEF.payment_mode) AS PAYMENT_MODE, NULL AS IMPORT_DATE, NULL AS LAST_UPDATE_DATE, null AS invoice_date, NULL AS company_name, \"Customer\'s Delivery Pincode\" AS pin_code, NULL AS FINAL_UTM_CAMPAIGN, \'Synced\' AS EasyEcom_Sync_Flag, CASE WHEN cancel_sales IS NOT NULL THEN LAST_UPDATE_DATE END AS cancelled_at, \'Meesho\' AS Data_Source ,s.sku as exception_sku from rpsg_db.maplemonk.ecom_flipkart_seller_report b LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )eef ON b.\"Order ID\" = EEF.reference_code AND (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = LOWER(EEF.SKU) INNER JOIN ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null ) where rw=1 ) S ON (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = (LOWER(S.sku)); create or replace table RPSG_DB.maplemonk.sales_consolidated_intermediate_ecom as select * from RPSG_DB.maplemonk.sales_consolidated_intermediate_ecom union all ( select * from rpsg_db.maplemonk.sales_consolidated_amazon_ecom_orders where (concat(ifnull(reference_code,\'\'),ifnull(sku,\'\')) not in (select distinct concat(ifnull(reference_code,\'\'),ifnull(sku,\'\')) from RPSG_DB.maplemonk.sales_consolidated_intermediate_ecom where lower(marketplace) like any (\'%amazon%\',\'%meesho%\' , \'%flipkart%\') )) ); create or replace table RPSG_DB.maplemonk.sales_consolidated_intermediate_ecom as select *, upper(b.\"Mapped Status\") Final_Status ,pin.DELIVERY_STATE as mapped_state, DELIVERY_CITY as Mapped_City from RPSG_DB.maplemonk.sales_consolidated_intermediate_ecom a left join (select distinct status, \"Mapped Status\" from rpsg_db.maplemonk.shipment_status_mapping) b on lower(case when lower(a.order_status) like \'%cancel%\' then a.order_status else coalesce(a.shipping_status, a.order_status) end)= lower(b.status) left join ( select * from (select *,row_number() over(partition by DELIVERY_POSTCODE order by 1 )row_number from rpsg_db.maplemonk.pincode_city_mapping) where row_number=1 ) pin on pin.DELIVERY_POSTCODE = a.pin_code; create or replace table rpsg_DB.maplemonk.Final_customerID_ecom_drv as with new_phone_numbers as ( select phone, contact_num ,19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from rpsg_DB.maplemonk.sales_consolidated_intermediate_ecom ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email,maple_monk_id from ( select phone as contact_num,email from rpsg_DB.maplemonk.sales_consolidated_intermediate_ecom ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date::date) over(partition by customer_id_final) as acquisition_date, m.* from (select c.maple_monk_id as maple_monk_id_phone, o.* from rpsg_DB.maplemonk.SALES_CONSOLIDATED_INTERMEDIATE_ECOM o left join (select * from (select contact_num phone,maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from rpsg_DB.maplemonk.Final_customerID_ecom_drv) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10))m left join (select distinct maple_monk_id, email from rpsg_DB.maplemonk.Final_customerID_ecom_drv where contact_num is null )d on d.email = m.email ; ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre drop COLUMN new_customer_flag ; ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_PRE ADD COLUMN new_customer_flag varchar(50); ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre drop COLUMN new_customer_flag_month ; ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ADD COLUMN acquisition_marketplace varchar(16777216); ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre drop COLUMN ACQUISITION_DATE ; ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ADD COLUMN ACQUISITION_DATE timestamp; ALTER TABLE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ADD COLUMN SAME_DAY_ORDERNO number; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre AS A SET A.SAME_DAY_ORDERNO = B.rw FROM ( select distinct customer_id_final ,order_id ,rank() over (partition by customer_id_final, order_date order by order_date, order_id) as rw from rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre ) AS B Where A.order_id = B.order_id; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre AS A SET A.ACQUISITION_DATE = B.ACQUISITION_DATE FROM ( select distinct customer_id_final , min(order_Date) OVER ( partition BY customer_id_final) ACQUISITION_DATE from rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre B where (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\',\'returned\') end) and (case when lower(shipping_status) is null then 1=1 else lower(shipping_status) not in (\'cancelled\',\'returned\') end) ) AS B where A.customer_id_final = B.customer_id_final; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = ACQUISITION_DATE and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\',\'returned\') end) and (case when lower(shipping_status) is null then 1=1 else lower(shipping_status) not in (\'cancelled\',\'returned\') end) then \'New\' WHEN Order_Date < ACQUISITION_DATE or acquisition_date is null THEN \'Yet to make completed order\' WHEN Order_Date > ACQUISITION_DATE then \'Repeat\' END AS Flag FROM rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre )AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final AND A.order_date::date=B.Order_date::Date; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\',\'returned\') end) and (case when lower(shipping_status) is null then 1=1 else lower(shipping_status) not in (\'cancelled\',\'returned\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\',\'returned\') end) and (case when lower(shipping_status) is null then 1=1 else lower(shipping_status) in (\'cancelled\',\'returned\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date::date, \'month\') = Last_day(acquisition_date::date, \'month\') THEN \'New\' WHEN Last_day(order_date::date, \'month\') < Last_day(acquisition_date::date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date::date, \'month\') > Last_day(acquisition_date::date, \'month\') THEN \'Repeat\' END AS Flag FROM rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\',\'returned\') end) and (case when lower(shipping_status) is null then 1=1 else lower(shipping_status) not in (\'cancelled\',\'returned\') end) THEN \'New\' ELSE new_customer_flag_month END; CREATE OR replace temporary TABLE rpsg_DB.maplemonk.temp_source_ecom AS SELECT DISTINCT customer_id_final, channel , marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, channel, marketplace, Min(order_date) OVER ( partition BY customer_id_final) firstOrderdate FROM rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre where (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\',\'returned\') end) and (case when lower(shipping_status) is null then 1=1 else lower(shipping_status) not in (\'cancelled\',\'returned\') end)) res WHERE order_date=firstorderdate; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_pre AS a SET a.acquisition_channel=b.channel FROM rpsg_db.maplemonk.temp_source_ecom b WHERE a.customer_id_final = b.customer_id_final; UPDATE rpsg_DB.maplemonk.SALES_CONSOLIDATED_ECOM_DRV_